import json,tarfile,hashlib
from pathlib import Path
root=Path('/work/c8-ablation')
rows={}
for p in sorted(root.glob('*.json')):
 d=json.loads(p.read_text())
 if 'rounds' in d:
  rows[p.stem]=dict(second_round_us=d['rounds'][-1]['median_us'],kernel_count=d['kernel_count'],validation=d['validation'],kernels=d.get('kernels',{}))
report=dict(concurrency=8,workload='DeepSeek V4 Flash TP1 single-GPU decode, 1024 input / 1024 output shape envelope',gpu_parallelism='independent jobs distributed over all four gfx1250 GPUs',method='32 flat HIP-graph repetitions, 5 warmups, 40 alternating samples per path, median from second round only; grouped native timings include device launch gaps',inputs='Checkpoint weights for projections/MoE; fixed synthetic distinct-row inputs or perturbed saved decode input. Not a trace-weighted all-43-layer average.',limitations=['Isolated groups compile independently; their register pressure differs from full monokernel. Do not sum as full-layer latency.','SWA/CSA/HCA attention rows are alternative layer types; no summation across alternatives.','Native means installed ATOM/AITER native dispatch, including its existing fusions.','Standalone pre/post rows overlap with combined post-pre; use the combined row at the attention-to-FFN boundary.','Compression rows at position1024 are non-boundary, position1535 boundary; boundary frequencies 1/4 and 1/128.','Routing benchmark uses learned no-bias top6 sqrtsoftplus; not hash-based routing.','MoE weights are checkpoint layer0 all256experts, synthetic distinct rows; expert distribution is not a serving-averaged trace.','Cache staging and residual layout rows are implementation overhead, not matching native computation groups.','Small numerical differences retained in validation fields, not treated as exact equivalence. No new end-to-end accuracy/performance run.'],rows=rows)
(root/'RESULTS.json').write_text(json.dumps(report,indent=2))
main=[('mHC pre + RMSNorm','mhc_pre'),('Input quant + QA/KV + norms + QB + Q norm/RoPE','qkv'),('SWA attention + split-KV reduce (128 entries)','attention_t128'),('HCA attention + reduce (136 entries, envelope144)','attention_envelope144_valid136'),('CSA attention + reduce (384 entries, envelope640)','attention_envelope640_valid384'),('CSA attention + reduce (512 entries, envelope640)','attention_envelope640_valid512'),('CSA attention + reduce (640 entries)','attention_t640'),('Inverse RoPE + quant + OA + quant + OB','output_projection'),('Attention mHC post + FFN mHC pre/RMSNorm','mhc_post_pre'),('Router GEMM + shared expert quant/up/SwiGLU/down','shared_router'),('Top6 selection + expert routing metadata','routing'),('Input MXFP8 quant + routed MoE up/SwiGLU/down/reduce','routed_moe'),('Shared+routed sum + mHC post','combine_post'),('Identity CSA selection + index translation (384)','identity_csa_384')]
s=['# C8 group ablation — 2026-10-21','','All timings are microseconds per eight-token decode batch, second round only. Native is the installed ATOM/AITER dispatch. Jobs distributed across four GPUs.','','| Native operation group | Isolated monokernel group | Native µs | Fused µs |','|---|---|---:|---:|']
for label,key in main:
 d=rows[key];v=d['second_round_us'];name=', '.join(dict.fromkeys(k['name'] for k in d['kernels']['fused']))
 s.append(f"| {label} | `{name}` | {v['native']:.2f} | {v['fused']:.2f} |")
s+=['','Compression projection + pool/norm/RoPE/cache/state writes:','','| Variant | Native non-boundary / boundary µs | Fused non-boundary / boundary µs |','|---|---:|---:|']
for case,label in [(0,'Main ratio4'),(1,'Main ratio128'),(2,'Indexer ratio4 FP8')]:
 a=rows[f'compress_case{case}_pos1024']['second_round_us'];b=rows[f'compress_case{case}_pos1535']['second_round_us'];s.append(f"| {label} | {a['native']:.2f} / {b['native']:.2f} | {a['fused']:.2f} / {b['fused']:.2f} |")
s+=['','Extra monokernel stages:','','| Stage | µs |','|---|---:|']
for label,key in [('Compact SWA cache + metadata','cache_stage_128_128'),('Compact HCA cache + metadata','cache_stage_144_136'),('Compact CSA cache + metadata (384 valid)','cache_stage_640_384'),('Residual unshuffle','residual_unshuffle'),('Residual shuffle','residual_shuffle')]:s.append(f"| {label} | {rows[key]['second_round_us']['fused']:.2f} |")
s+=['','## Interpretation','','Largest isolated regressions: attention (~24–32 µs), routed MoE (~28 µs), post/pre boundary (~6.6 µs), routing (~4.2 µs). Cache compaction adds ~6–17 µs. Ratio128 compressor loses ~9.6 µs at rare boundary tokens. These are tuning targets, not an additive attribution of the full model slowdown.','','Attention uses 64 splits for every row: 8 × 4 head groups × 64 = 2048 tasks looped over 256 resident CTAs. Empty splits still initialize partials and reduction reads 64 splits. This is a concrete batching inefficiency worth tuning; no parameter changes were made in this study.','','## Scope and limitations','']+['- '+x for x in report['limitations']]+['','The scripts import saved dependencies from /work/batch-full, /work/modelwide, /work/ffn-c1, /work/full-attention-native, and /work/atom-actual-microbench. Preserve the previous full resume archive alongside this new ablation directory. Exact native kernel names and all samples are in individual JSON files; profiler traces provide names, not the primary timings.','', 'All experiment servers on ports11500/11600/11700/11800 were stopped before this study. All ablation workers have finished.']
(root/'RESULTS.md').write_text('\n'.join(s)+'\n')
